import { betterFetch } from "@better-fetch/fetch";
import type { JWTPayload } from "jose";
import { decodeJwt, decodeProtectedHeader, importJWK, jwtVerify } from "jose";
import { logger } from "../env";
import { APIError, BetterAuthError } from "../error";
import type { OAuthProvider, ProviderOptions } from "../oauth2";
import {
	createAuthorizationURL,
	getPrimaryClientId,
	refreshAccessToken,
	validateAuthorizationCode,
} from "../oauth2";

export interface GoogleProfile {
	aud: string;
	azp: string;
	email: string;
	email_verified: boolean;
	exp: number;
	/**
	 * The family name of the user, or last name in most
	 * Western languages.
	 */
	family_name: string;
	/**
	 * The given name of the user, or first name in most
	 * Western languages.
	 */
	given_name: string;
	hd?: string | undefined;
	iat: number;
	iss: string;
	jti?: string | undefined;
	locale?: string | undefined;
	name: string;
	nbf?: number | undefined;
	picture: string;
	sub: string;
}

export interface GoogleOptions extends ProviderOptions<GoogleProfile> {
	clientId: string | string[];
	/**
	 * The access type to use for the authorization code request
	 */
	accessType?: ("offline" | "online") | undefined;
	/**
	 * The display mode to use for the authorization code request
	 */
	display?: ("page" | "popup" | "touch" | "wap") | undefined;
	/**
	 * The hosted domain (Google Workspace) the user must belong to.
	 *
	 * This is sent to Google as the `hd` authorization hint and, when set, is
	 * also enforced against the `hd` claim of the returned id token/profile.
	 * Set `hd: "*"` to require any Workspace hosted-domain claim. Sign-in is
	 * rejected when the claim is missing or does not satisfy this restriction.
	 */
	hd?: string | undefined;
	/**
	 * Whether to send `include_granted_scopes=true` to Google's authorization
	 * endpoint, which lets new access tokens cover scopes from prior grants
	 * in addition to the ones requested for this flow. Set to `false` when
	 * each OAuth flow should request only its own scopes.
	 *
	 * Defaults to `true`.
	 *
	 * @see https://developers.google.com/identity/protocols/oauth2/web-server#incrementalAuth
	 */
	includeGrantedScopes?: boolean | undefined;
}

const GOOGLE_ID_TOKEN_MAX_AGE = "1h";
const GOOGLE_ID_TOKEN_ALGORITHM = "RS256";
type GoogleIdTokenAlgorithm = typeof GOOGLE_ID_TOKEN_ALGORITHM;
const GOOGLE_ID_TOKEN_ALGORITHMS: GoogleIdTokenAlgorithm[] = [
	GOOGLE_ID_TOKEN_ALGORITHM,
];

function isGoogleIdTokenAlgorithm(
	algorithm: unknown,
): algorithm is GoogleIdTokenAlgorithm {
	return GOOGLE_ID_TOKEN_ALGORITHMS.includes(
		algorithm as GoogleIdTokenAlgorithm,
	);
}

export interface VerifyGoogleIdTokenOptions {
	token: string;
	audience: string | string[];
	nonce?: string | undefined;
}

/**
 * Verifies a Google ID token against Google's issuer, audience, signature,
 * expiry, and maximum token age.
 */
export const verifyGoogleIdToken = async ({
	token,
	audience,
	nonce,
}: VerifyGoogleIdTokenOptions): Promise<JWTPayload | null> => {
	try {
		const { kid, alg } = decodeProtectedHeader(token);
		if (!isGoogleIdTokenAlgorithm(alg)) return null;

		const publicKeys = await getGooglePublicKeys(kid);
		for (const publicKey of publicKeys) {
			try {
				const { payload: jwtClaims } = await jwtVerify(token, publicKey, {
					algorithms: GOOGLE_ID_TOKEN_ALGORITHMS,
					issuer: ["https://accounts.google.com", "accounts.google.com"],
					audience,
					maxTokenAge: GOOGLE_ID_TOKEN_MAX_AGE,
				});

				if (nonce && jwtClaims.nonce !== nonce) {
					return null;
				}

				return jwtClaims;
			} catch {
				continue;
			}
		}

		return null;
	} catch {
		return null;
	}
};

/**
 * Checks whether Google's verified `hd` claim satisfies the configured hosted
 * domain restriction. `hd: "*"` accepts any Google Workspace hosted domain.
 */
export const isGoogleHostedDomainAllowed = (
	configuredHostedDomain: string | undefined,
	tokenHostedDomain: unknown,
) => {
	if (!configuredHostedDomain) return true;
	if (typeof tokenHostedDomain !== "string" || !tokenHostedDomain) {
		return false;
	}
	if (configuredHostedDomain === "*") return true;
	return tokenHostedDomain === configuredHostedDomain;
};

export const google = (options: GoogleOptions) => {
	return {
		id: "google",
		name: "Google",
		accountSubject: ({ profile }) => profile.sub,
		async createAuthorizationURL({
			state,
			scopes,
			codeVerifier,
			redirectURI,
			loginHint,
			display,
			additionalParams,
		}) {
			if (!getPrimaryClientId(options.clientId) || !options.clientSecret) {
				logger.error(
					"Client Id and Client Secret is required for Google. Make sure to provide them in the options.",
				);
				throw new BetterAuthError("CLIENT_ID_AND_SECRET_REQUIRED");
			}
			if (!codeVerifier) {
				throw new BetterAuthError("codeVerifier is required for Google");
			}
			const _scopes = options.disableDefaultScope
				? []
				: ["email", "profile", "openid"];
			if (options.scope) _scopes.push(...options.scope);
			if (scopes) _scopes.push(...scopes);
			const url = await createAuthorizationURL({
				id: "google",
				options,
				authorizationEndpoint: "https://accounts.google.com/o/oauth2/v2/auth",
				scopes: _scopes,
				state,
				codeVerifier,
				redirectURI,
				prompt: options.prompt,
				accessType: options.accessType,
				display: display || options.display,
				loginHint,
				hd: options.hd,
				additionalParams: {
					...(options.includeGrantedScopes === false
						? {}
						: { include_granted_scopes: "true" }),
					...(additionalParams ?? {}),
				},
			});
			return url;
		},
		validateAuthorizationCode: async ({ code, codeVerifier, redirectURI }) => {
			return validateAuthorizationCode({
				code,
				codeVerifier,
				redirectURI,
				options,
				tokenEndpoint: "https://oauth2.googleapis.com/token",
			});
		},
		refreshAccessToken: options.refreshAccessToken
			? options.refreshAccessToken
			: async (refreshToken) => {
					return refreshAccessToken({
						refreshToken,
						options: {
							clientId: options.clientId,
							clientKey: options.clientKey,
							clientSecret: options.clientSecret,
						},
						tokenEndpoint: "https://oauth2.googleapis.com/token",
					});
				},
		idToken: {
			// https://developers.google.com/identity/sign-in/web/backend-auth#verify-the-integrity-of-the-id-token
			jwks: (header) => getGooglePublicKey(header.kid!),
			issuer: ["https://accounts.google.com", "accounts.google.com"],
			audience: options.clientId,
			maxTokenAge: GOOGLE_ID_TOKEN_MAX_AGE,
			// Google's `hd` authorization parameter is only a UI hint and can be
			// removed or changed by the user. When a hosted domain is configured,
			// the `hd` claim in the verified id token is the authoritative value
			// and must satisfy the configured restriction, otherwise accounts
			// outside the workspace domain would be accepted on the id_token path.
			verifyClaims: options.hd
				? (claims) => isGoogleHostedDomainAllowed(options.hd, claims.hd)
				: undefined,
		},
		async getUserInfo(token) {
			if (options.getUserInfo) {
				return options.getUserInfo(token);
			}
			if (!token.idToken) {
				return null;
			}
			const user = decodeJwt(token.idToken) as GoogleProfile;
			// Enforce the configured hosted domain on the callback profile path.
			// The authorization-time `hd` value is only a UI hint; the verified
			// token/profile claim is the authoritative Workspace signal.
			if (!isGoogleHostedDomainAllowed(options.hd, user.hd)) {
				logger.error(
					`Google sign-in rejected: id token hosted domain (hd) "${
						user.hd ?? "<missing>"
					}" does not satisfy the configured "hd" option "${options.hd}".`,
				);
				return null;
			}
			const userMap = await options.mapProfileToUser?.(user);
			return {
				user: {
					name: user.name,
					email: user.email,
					image: user.picture,
					emailVerified: user.email_verified,
					...userMap,
				},
				data: user,
			};
		},
		options,
	} satisfies OAuthProvider<GoogleProfile>;
};

export const getGooglePublicKey = async (kid: string) => {
	const [publicKey] = await getGooglePublicKeys(kid);
	if (!publicKey) {
		throw new Error(`JWK with kid ${kid} not found`);
	}
	return publicKey;
};

const getGooglePublicKeys = async (kid?: string) => {
	const { data } = await betterFetch<{
		keys: Array<{
			kid: string;
			alg?: string;
			kty: string;
			use: string;
			n: string;
			e: string;
		}>;
	}>("https://www.googleapis.com/oauth2/v3/certs");

	if (!data?.keys) {
		throw new APIError("BAD_REQUEST", {
			message: "Keys not found",
		});
	}

	const jwks = kid ? data.keys.filter((key) => key.kid === kid) : data.keys;
	if (!jwks.length) {
		throw new Error(`JWK with kid ${kid} not found`);
	}

	return Promise.all(
		jwks.map((jwk) => importJWK(jwk, GOOGLE_ID_TOKEN_ALGORITHM)),
	);
};

import { createAuthEndpoint } from "@better-auth/core/api";
import type { AccountKey } from "@better-auth/core/db";
import type { OAuth2Tokens } from "@better-auth/core/oauth2";
import { safeJSONParse } from "@better-auth/core/utils/json";
import { appendQueryParams } from "@better-auth/core/utils/url";
import * as z from "zod";
import { getAwaitableValue } from "../../context/helpers";
import { setSessionCookie } from "../../cookies";
import {
	resolveOAuthAccountKey,
	toOAuthProfileRecord,
} from "../../oauth2/account-key";
import {
	missingEmailLogMessage,
	OAUTH_CALLBACK_ERROR_CODES,
} from "../../oauth2/errors";
import {
	handleOAuthUserInfo,
	linkOAuthAccount,
} from "../../oauth2/link-account";
import {
	generateIdTokenNonce,
	generateState,
	parseState,
} from "../../oauth2/state";
import { getOAuthCallbackPath } from "../../oauth2/utils";
import { HIDE_METADATA } from "../../utils/hide-metadata";
import { isAPIError } from "../../utils/is-api-error";

const schema = z.object({
	code: z.string().optional(),
	error: z.string().optional(),
	device_id: z.string().optional(),
	error_description: z.string().optional(),
	state: z.string().optional(),
	user: z.string().optional(),
	iss: z.string().optional(),
});

export const callbackOAuth = createAuthEndpoint(
	"/callback/:id",
	{
		method: ["GET", "POST"],
		operationId: "handleOAuthCallback",
		body: schema.optional(),
		query: schema.optional(),
		metadata: {
			...HIDE_METADATA,
			allowedMediaTypes: [
				"application/x-www-form-urlencoded",
				"application/json",
			],
		},
	},
	async (c) => {
		let queryOrBody: z.infer<typeof schema>;
		const defaultErrorURL =
			c.context.options.onAPIError?.errorURL || `${c.context.baseURL}/error`;

		// Handle POST requests by redirecting to GET to ensure cookies are sent
		if (c.method === "POST") {
			const postData = c.body ? schema.parse(c.body) : {};
			const queryData = c.query ? schema.parse(c.query) : {};

			const mergedData = schema.parse({ ...postData, ...queryData });
			const params = new URLSearchParams();

			for (const [key, value] of Object.entries(mergedData)) {
				if (value !== undefined && value !== null) {
					params.set(key, String(value));
				}
			}

			const redirectURL = `${c.context.baseURL}/callback/${c.params.id}?${params.toString()}`;
			throw c.redirect(redirectURL);
		}

		try {
			if (c.method === "GET") {
				queryOrBody = schema.parse(c.query);
			} else if (c.method === "POST") {
				queryOrBody = schema.parse(c.body);
			} else {
				throw new Error("Unsupported method");
			}
		} catch (e) {
			c.context.logger.error("INVALID_CALLBACK_REQUEST", e);
			const params = new URLSearchParams({
				error: "invalid_callback_request",
			});
			const redirectURL = appendQueryParams(defaultErrorURL, params);

			throw c.redirect(redirectURL);
		}

		const {
			code,
			error,
			state,
			error_description,
			device_id,
			user: userData,
			iss,
		} = queryOrBody;

		if (state === undefined && code) {
			const provider = await getAwaitableValue(c.context.socialProviders, {
				value: c.params.id,
			});
			if (provider?.allowIdpInitiated) {
				const idTokenNonce = generateIdTokenNonce(provider);
				const { state: freshState, codeVerifier } = await generateState(c, {
					idTokenNonce,
				});
				const authUrl = await provider.createAuthorizationURL({
					state: freshState,
					codeVerifier,
					idTokenNonce,
					redirectURI: `${c.context.baseURL}${getOAuthCallbackPath(provider)}`,
				});
				throw c.redirect(authUrl.toString());
			}
		}

		if (!state) {
			c.context.logger.error("State not found", error);
			const params = new URLSearchParams({ error: "state_not_found" });
			const redirectURL = appendQueryParams(defaultErrorURL, params);

			throw c.redirect(redirectURL);
		}

		const {
			codeVerifier,
			callbackURL,
			link,
			errorURL,
			newUserURL,
			requestSignUp,
			idTokenNonce,
		} = await parseState(c);

		function redirectOnError(error: string, description?: string | undefined) {
			const baseURL = errorURL ?? defaultErrorURL;

			const params = new URLSearchParams({ error });
			if (description) params.set("error_description", description);

			const redirectURL = appendQueryParams(baseURL, params);

			throw c.redirect(redirectURL);
		}

		if (error) {
			redirectOnError(error, error_description);
		}

		if (!code) {
			c.context.logger.warn("Code not found");
			throw redirectOnError(OAUTH_CALLBACK_ERROR_CODES.NO_CODE);
		}

		const provider = await getAwaitableValue(c.context.socialProviders, {
			value: c.params.id,
		});

		if (!provider) {
			c.context.logger.warn("OAuth provider not found", {
				providerId: c.params.id,
			});
			throw redirectOnError(OAUTH_CALLBACK_ERROR_CODES.PROVIDER_NOT_FOUND);
		}

		// RFC 9207: validate authorization server issuer identifier.
		// Only validated when the provider sends the iss parameter;
		// older OAuth servers that don't support RFC 9207 omit it.
		if (iss && provider.issuer && iss !== provider.issuer) {
			c.context.logger.error("OAuth issuer mismatch", {
				expected: provider.issuer,
				received: iss,
			});
			throw redirectOnError(OAUTH_CALLBACK_ERROR_CODES.ISSUER_MISMATCH);
		}

		// Fail closed: a provider that requires id_token nonce binding must carry
		// an expected nonce recovered from state. If it is absent (a flow minted
		// before binding was enabled, or a dropped state field), the redirect
		// cannot enforce the binding, so refuse rather than trust an unbound
		// id_token.
		if (provider.requiresIdTokenNonce && !idTokenNonce) {
			c.context.logger.error(
				"OAuth id_token nonce binding required but no expected nonce was found in state",
				{ providerId: provider.id },
			);
			throw redirectOnError(OAUTH_CALLBACK_ERROR_CODES.NONCE_BINDING_MISSING);
		}

		let tokens: OAuth2Tokens | null;
		try {
			tokens = await provider.validateAuthorizationCode({
				code: code,
				codeVerifier,
				deviceId: device_id,
				redirectURI: `${c.context.baseURL}${getOAuthCallbackPath(provider)}`,
			});
		} catch (e) {
			c.context.logger.error("", e);
			throw redirectOnError(OAUTH_CALLBACK_ERROR_CODES.INVALID_CODE);
		}
		if (!tokens) {
			throw redirectOnError(OAUTH_CALLBACK_ERROR_CODES.INVALID_CODE);
		}
		const parsedUserData = userData
			? safeJSONParse<{
					name?: {
						firstName?: string;
						lastName?: string;
					};
					email?: string;
				}>(userData)
			: null;

		const providerResult = await provider.getUserInfo({
			...tokens,
			...(idTokenNonce ? { expectedIdTokenNonce: idTokenNonce } : {}),
			/**
			 * The user object from the provider
			 * This is only available for some providers like Apple
			 */
			user: parsedUserData ?? undefined,
		});
		if (!providerResult?.user) {
			c.context.logger.error("Unable to get user info");
			return redirectOnError(
				OAUTH_CALLBACK_ERROR_CODES.UNABLE_TO_GET_USER_INFO,
			);
		}
		const userInfo = providerResult.user;
		const providerProfile = toOAuthProfileRecord(providerResult.data);
		let accountKey: AccountKey;
		try {
			accountKey = await resolveOAuthAccountKey(
				provider,
				tokens,
				providerResult.data,
			);
		} catch (error) {
			c.context.logger.error("Unable to derive provider account identity", {
				providerId: provider.id,
				error,
			});
			return redirectOnError(
				OAUTH_CALLBACK_ERROR_CODES.UNABLE_TO_GET_USER_INFO,
			);
		}
		const { accountId } = accountKey;

		if (!callbackURL) {
			c.context.logger.error("No callback URL found");
			throw redirectOnError(OAUTH_CALLBACK_ERROR_CODES.NO_CALLBACK_URL);
		}
		const accountData = {
			...accountKey,
			...tokens,
			scope: tokens.scopes?.join(","),
		};

		if (link) {
			const linkResult = await linkOAuthAccount(c, {
				link,
				userInfo,
				account: accountData,
				profile: providerProfile,
				scopes: tokens.scopes,
			});
			if (!linkResult.linked) {
				return redirectOnError(linkResult.error.code, linkResult.error.message);
			}
			throw c.redirect(callbackURL);
		}

		if (!userInfo.email) {
			c.context.logger.error(missingEmailLogMessage(provider.id));
			return redirectOnError(OAUTH_CALLBACK_ERROR_CODES.EMAIL_NOT_FOUND);
		}
		let result: Awaited<ReturnType<typeof handleOAuthUserInfo>>;
		try {
			result = await handleOAuthUserInfo(c, {
				userInfo: {
					...userInfo,
					id: accountId,
					email: userInfo.email,
					name: userInfo.name || "",
				},
				account: accountData,
				callbackURL,
				disableSignUp:
					(provider.disableImplicitSignUp && !requestSignUp) ||
					provider.options?.disableSignUp,
				overrideUserInfo: provider.options?.overrideUserInfoOnSignIn,
				source: {
					method: "oauth",
					oauth: { providerId: provider.id, profile: providerProfile },
				},
			});
		} catch (e) {
			// App-defined rejection codes are forwarded verbatim rather than mapped
			// onto OAUTH_CALLBACK_ERROR_CODES.
			if (isAPIError(e) && e.body?.code) {
				redirectOnError(e.body.code, e.body.message);
			}
			throw e;
		}
		if (result.error) {
			c.context.logger.error(result.error.split(" ").join("_"));
			return redirectOnError(result.error.split(" ").join("_"));
		}
		const { session, user } = result.data!;
		await setSessionCookie(c, {
			session,
			user,
		});

		let toRedirectTo: string;
		try {
			const url = result.isRegister ? newUserURL || callbackURL : callbackURL;
			toRedirectTo = url.toString();
		} catch {
			toRedirectTo = result.isRegister
				? newUserURL || callbackURL
				: callbackURL;
		}
		throw c.redirect(toRedirectTo);
	},
);

import type { AccountKey } from "@better-auth/core/db";
import {
	APIError,
	BASE_ERROR_CODES,
	BetterAuthError,
} from "@better-auth/core/error";
import type { OAuth2Tokens, OAuthProvider } from "@better-auth/core/oauth2";

/**
 * Exposes a provider-declared profile as the raw claim record used by
 * provisioning hooks. Provider profile interfaces are object-shaped but do
 * not need an index signature solely to satisfy this erased boundary.
 */
export function toOAuthProfileRecord(profile: object): Record<string, unknown> {
	return profile as Record<string, unknown>;
}

/**
 * Resolves the stable account key established by an OAuth provider response.
 */
export async function resolveOAuthAccountKey<Profile extends object>(
	provider: OAuthProvider<Profile>,
	tokens: OAuth2Tokens,
	profile: Profile,
): Promise<AccountKey> {
	const accountKeyContext = { tokens, profile };
	const accountSubject = provider.accountSubject;
	const resolvedSubject = await accountSubject(accountKeyContext);
	const accountId = String(resolvedSubject);
	if (
		(typeof resolvedSubject === "number" &&
			!Number.isFinite(resolvedSubject)) ||
		accountId.trim().length === 0 ||
		accountId === "undefined" ||
		accountId === "null"
	) {
		throw new BetterAuthError("OAUTH_ACCOUNT_SUBJECT_INVALID");
	}

	return { providerId: provider.id, accountId };
}

/**
 * Resolves an OAuth account key at a direct HTTP authentication boundary.
 *
 * Provider resolvers are application code and can reject or return malformed
 * values. Direct sign-in and linking expose all such failures as one stable
 * authentication error instead of leaking implementation details or a 500.
 */
export async function resolveOAuthAccountKeyForAPI<Profile extends object>(
	provider: OAuthProvider<Profile>,
	tokens: OAuth2Tokens,
	profile: Profile,
): Promise<AccountKey> {
	try {
		return await resolveOAuthAccountKey(provider, tokens, profile);
	} catch {
		throw APIError.from(
			"UNAUTHORIZED",
			BASE_ERROR_CODES.FAILED_TO_GET_USER_INFO,
		);
	}
}

import type { GenericEndpointContext } from "@better-auth/core";
import { APIError, BASE_ERROR_CODES } from "@better-auth/core/error";
import { getOAuthServerContext, setOAuthState } from "../api/state/oauth";
import { generateRandomString } from "../crypto";
import type { StateData } from "../state";
import { generateGenericState, parseGenericState, StateError } from "../state";
import { redirectOnError } from "./errors";

/**
 * Mint the OIDC `nonce` for the redirect flow, or `undefined` when the provider
 * does not require ID-token nonce binding. Every redirect entrypoint (social
 * sign-in, account linking, IDP-initiated bounce, and the OAuth popup) mints
 * through this helper, so the value sent on the authorization URL and the value
 * persisted in state are produced one way and cannot drift apart.
 */
export function generateIdTokenNonce(provider: {
	requiresIdTokenNonce?: boolean | undefined;
}): string | undefined {
	return provider.requiresIdTokenNonce ? generateRandomString(32) : undefined;
}

/**
 * Inputs for {@link generateState}. Grouped into one object so call sites read
 * by name instead of by position.
 */
export interface GenerateStateOptions {
	/** Link target when this flow links a provider identity to an existing user. */
	link?: { email: string; userId: string } | undefined;
	/** Extra data to round-trip through state; `false` writes none. */
	additionalData?: Record<string, any> | false | undefined;
	/** The `state` nonce already used to build the authorization URL. Minted when omitted. */
	state?: string | undefined;
	/** The PKCE `codeVerifier` already used to build the authorization URL. Minted when omitted. */
	codeVerifier?: string | undefined;
	/** The OIDC nonce already sent as the authorization URL `nonce` parameter. */
	idTokenNonce?: string | undefined;
}

export async function generateState(
	c: GenericEndpointContext,
	options?: GenerateStateOptions,
) {
	const callbackURL = c.body?.callbackURL || c.context.options.baseURL;
	if (!callbackURL) {
		throw APIError.from("BAD_REQUEST", BASE_ERROR_CODES.CALLBACK_URL_REQUIRED);
	}

	const codeVerifier = options?.codeVerifier ?? generateRandomString(128);

	const pendingServerContext = await getOAuthServerContext();
	const serverContext =
		pendingServerContext && Object.keys(pendingServerContext).length
			? pendingServerContext
			: undefined;

	const stateData: StateData = {
		...(options?.additionalData ? options.additionalData : {}),
		callbackURL,
		codeVerifier,
		errorURL: c.body?.errorCallbackURL,
		newUserURL: c.body?.newUserCallbackURL,
		link: options?.link,
		// Assigned after the client-controlled `additionalData` spread so a client
		// cannot smuggle a `serverContext` of its own through the request body.
		serverContext,
		expiresAt: Date.now() + 10 * 60 * 1000,
		requestSignUp: c.body?.requestSignUp,
		idTokenNonce: options?.idTokenNonce,
	};

	await setOAuthState(stateData);

	try {
		return generateGenericState(c, stateData);
	} catch (error) {
		c.context.logger.error("Failed to create verification", error);
		throw new APIError("INTERNAL_SERVER_ERROR", {
			message: "Unable to create verification",
			cause: error,
		});
	}
}

export async function parseState(c: GenericEndpointContext) {
	const state = c.query.state || c.body?.state;
	const errorURL =
		c.context.options.onAPIError?.errorURL || `${c.context.baseURL}/error`;

	let parsedData: StateData;

	try {
		parsedData = await parseGenericState(c, state);
	} catch (error) {
		c.context.logger.error("Failed to parse state", error);

		let code = "internal_server_error";
		let redirectErrorURL = errorURL;
		if (error instanceof StateError) {
			code =
				error.code === "state_security_mismatch"
					? "state_mismatch"
					: error.code;
			redirectErrorURL = error.errorURL || errorURL;
		}
		redirectOnError(c, redirectErrorURL, code);
	}

	if (!parsedData.errorURL) {
		parsedData.errorURL = errorURL;
	}

	if (parsedData) {
		await setOAuthState(parsedData);
	}

	return parsedData;
}

### Initialize Neon Serverless database client in src/db/index.ts

Source: https://github.com/drizzle-team/drizzle-orm-docs/blob/main/src/content/docs/tutorials/drizzle-with-vercel-edge-functions.mdx

Instantiate the Drizzle client configured with the neon-serverless driver using the POSTGRES_URL environment variable.

```typescript
import { drizzle } from 'drizzle-orm/neon-serverless';


export const db = drizzle(process.env.POSTGRES_URL!)
```

--------------------------------

### Initialize Neon WebSockets driver with existing Pool instance

Source: https://github.com/drizzle-team/drizzle-orm-docs/blob/main/src/content/docs/pg/connect-neon.mdx

Passes an existing Neon Pool client instance to Drizzle ORM. Requires the '@neondatabase/serverless' package.

```typescript
// Make sure to install the '@neondatabase/serverless' package 
import { Pool } from '@neondatabase/serverless';
import { drizzle } from 'drizzle-orm/neon-serverless';

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const db = drizzle({ client: pool })

const result = await db.execute('select 1');
```

--------------------------------

### Connect using Neon WebSocket driver in serverless environments

Source: https://github.com/drizzle-team/drizzle-orm-docs/blob/main/src/content/docs/pg/connect-planetscale-postgres.mdx

Use the Neon WebSocket driver for interactive transactions or session-based features in serverless platforms. Requires setting pipelineConnect to false and defining wsProxy.

```typescript
import { Pool, neonConfig } from '@neondatabase/serverless';
import { drizzle } from 'drizzle-orm/neon-serverless';

// Required for PlanetScale Postgres connections
neonConfig.pipelineConnect = false;
neonConfig.wsProxy = (host, port) => `${host}/v2?address=${host}:${port}`;

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const db = drizzle({ client: pool });

const result = await db.execute('select 1');
```

--------------------------------

### Install node-postgres driver and Drizzle packages for Neon

Source: https://github.com/drizzle-team/drizzle-orm-docs/blob/main/src/content/docs/pg/connect-neon.mdx

Installs the node-postgres pg driver and Drizzle packages for connecting to Neon from serverful Node.js environments.

```shell
drizzle-orm@rc pg
-D drizzle-kit@rc
```

### Edge-compatible driver

Source: https://github.com/drizzle-team/drizzle-orm-docs/blob/main/src/content/docs/tutorials/drizzle-with-vercel-edge-functions.mdx

When using Drizzle ORM with Vercel Edge functions you have to use edge-compatible drivers because the functions run in [Edge runtime](https://vercel.com/docs/functions/runtimes/edge-runtime) not in Node.js runtime, so there are some limitations of standard Node.js APIs.

You can choose one of these drivers according to your database dialect:

- [Neon serverless driver](/docs/get-started-postgresql#neon) allows you to query your Neon Postgres databases from serverless and edge environments over HTTP or WebSockets in place of TCP. We recommend using this driver for connecting to `Neon Postgres`.
- [Vercel Postgres driver](/docs/get-started-postgresql#vercel-postgres) is built on top of the `Neon serverless driver`. We recommend using this driver for connecting to `Vercel Postgres`.
- [PlanetScale serverless driver](/docs/mysql/get-started-mysql#planetscale) allows you access any `MySQL` client and execute queries over an HTTP connection, which is generally not blocked by cloud providers.
- [libSQL client](/docs/sqlite/get-started-sqlite#turso) allows you to access [Turso](https://docs.turso.tech/introduction) database.

### Configure webServer in playwright.config.ts

Source: https://github.com/microsoft/playwright/blob/main/docs/src/test-webserver-js.md

Configures Playwright to launch a local development server using a shell command before starting tests. Sets the server to be reused in non-CI environments and configures standard I/O piping.

```javascript
import { defineConfig } from '@playwright/test';

export default defineConfig({
  // Run your local dev server before starting the tests
  webServer: {
    command: 'npm run start',
    url: 'http://localhost:3000',
    reuseExistingServer: !process.env.CI,
    stdout: 'ignore',
    stderr: 'pipe',
  },
});
```

--------------------------------

### Configure webServer wait pattern and use captured environment variables in tests

Source: https://github.com/microsoft/playwright/blob/main/docs/src/release-notes-js.md

Configure Playwright to wait for a webserver stdout regular expression and access named capture groups as environment variables in test files. This enables waiting for non-HTTP readiness checks or capturing dynamic ports.

```javascript
import { defineConfig } from '@playwright/test';

export default defineConfig({
  webServer: {
    command: 'npm run start',
    wait: {
      stdout: /Listening on port (?<my_server_port>\d+)/
    },
  },
});
```

```javascript
import { test, expect } from '@playwright/test';

test.use({ baseURL: `http://localhost:${process.env.MY_SERVER_PORT ?? 3000}` });

test('homepage', async ({ page }) => {
  await page.goto('/');
});
```

--------------------------------

### Configure outputDir, globalSetup, globalTeardown, and timeout in playwright.config.ts

Source: https://github.com/microsoft/playwright/blob/main/docs/src/test-configuration-js.md

Set advanced options including paths to global setup and teardown files, the output folder for artifacts, and test execution timeouts. Global setup and teardown files must export a single function.

```javascript
import { defineConfig } from '@playwright/test';

export default defineConfig({
  // Folder for test artifacts such as screenshots, videos, traces, etc.
  outputDir: 'test-results',

  // path to the global setup files.
  globalSetup: require.resolve('./global-setup'),

  // path to the global teardown files.
  globalTeardown: require.resolve('./global-teardown'),

  // Each test is given 30 seconds.
  timeout: 30000,

});
```

