+import "server-only";
+import { eq } from "drizzle-orm";
+import { z } from "zod";
+import { db } from "./db";
+import { workspaceIdentity } from "./schema";
+
+const identitySchema = z.object({
+  sub: z.string().min(1).max(255),
+  hd: z.string().min(1),
+  email: z.email(),
+  email_verified: z.literal(true),
+});
+const profileSchema = z.object({
+  id: z.string().min(1),
+  primaryEmail: z.email(),
+  name: z.object({ fullName: z.string() }).optional(),
+  emails: z.array(z.object({ address: z.email(), type: z.string().optional(), customType: z.string().optional() })).optional(),
+  phones: z.array(z.object({ value: z.string(), type: z.string().optional(), customType: z.string().optional() })).optional(),
+});
+
+export class WorkspaceUnavailable extends Error {
+  constructor(public readonly reconnect = false) {
+    super(reconnect ? "Reconnect your Google account" : "Workspace profile unavailable");
+  }
+}
+
+export function validateIdentity(input: unknown) {
+  const identity = identitySchema.parse(input);
+  if (!process.env.GOOGLE_WORKSPACE_DOMAIN || identity.hd !== process.env.GOOGLE_WORKSPACE_DOMAIN) throw new WorkspaceUnavailable(true);
+  return identity;
+}
+
+async function googleGet(url: string, accessToken: string) {
+  const response = await fetch(url, {
+    headers: { Authorization: `Bearer ${accessToken}` },
+    cache: "no-store",
+    signal: AbortSignal.timeout(10_000),
+  });
+  if (!response.ok) throw new WorkspaceUnavailable(response.status === 401 || response.status === 403);
+  return response.json();
+}
+
+export async function readWorkspaceProfile(accessToken: string, subject: string, bind = false) {
+  const identity = validateIdentity(await googleGet("https://openidconnect.googleapis.com/v1/userinfo", accessToken));
+  if (identity.sub !== subject) throw new WorkspaceUnavailable(true);
+  const [binding] = await db.select().from(workspaceIdentity).where(eq(workspaceIdentity.googleSubject, subject));
+  if (!binding && !bind) throw new WorkspaceUnavailable(true);
+  const url = new URL(`https://admin.googleapis.com/admin/directory/v1/users/${encodeURIComponent(binding?.directoryId ?? identity.email)}`);
+  url.searchParams.set("viewType", "domain_public");
+  url.searchParams.set("fields", "id,primaryEmail,name(fullName),emails(address,type,customType),phones(value,type,customType)");
+  const profile = profileSchema.parse(await googleGet(url.toString(), accessToken));
+  // Email is a fresh consistency check, never the durable identity key. During
+  // rename propagation fail closed rather than resolving a different account.
+  if (profile.primaryEmail.toLowerCase() !== identity.email.toLowerCase() || (binding && profile.id !== binding.directoryId)) throw new WorkspaceUnavailable(true);
+  if (!binding) {
+    // Recheck the token's current owner before establishing the first binding.
+    const current = validateIdentity(await googleGet("https://openidconnect.googleapis.com/v1/userinfo", accessToken));
+    if (current.sub !== subject || current.email.toLowerCase() !== profile.primaryEmail.toLowerCase()) throw new WorkspaceUnavailable(true);
+    await db.insert(workspaceIdentity).values({ googleSubject: subject, directoryId: profile.id }).onConflictDoNothing();
+    const [saved] = await db.select().from(workspaceIdentity).where(eq(workspaceIdentity.googleSubject, subject));
+    if (saved?.directoryId !== profile.id) throw new WorkspaceUnavailable(true);
+  }
+  return profile;
+}

