+"use client";
+
+import { createAuthClient } from "better-auth/react";
+import { useState } from "react";
+import { Button } from "@/components/ui/button";
+
+const client = createAuthClient();
+
+export function AuthButton({ action = "sign-in" }: { action?: "sign-in" | "sign-out" | "reconnect" }) {
+  const [pending, setPending] = useState(false);
+  const [error, setError] = useState(false);
+  async function run() {
+    setPending(true);
+    setError(false);
+    try {
+      if (action === "sign-out") {
+        const result = await client.signOut();
+        if (result.error) throw new Error();
+        window.location.replace("/");
+      } else {
+        if (action === "reconnect") {
+          const result = await client.signOut();
+          if (result.error) throw new Error();
+        }
+        const result = await client.signIn.social({ provider: "google", callbackURL: "/profile", errorCallbackURL: "/?error=sign-in" });
+        if (result.error) throw new Error();
+      }
+    } catch {
+      setError(true);
+      setPending(false);
+    }
+  }
+  return (
+    <div className="space-y-2">
+      <Button onClick={run} disabled={pending} size="lg">
+        {pending ? "Please wait…" : action === "sign-out" ? "Sign out" : action === "reconnect" ? "Reconnect Google" : "Sign in with Google"}
+      </Button>
+      {error && <p role="alert" className="text-sm text-destructive">Unable to complete that request. Please try again.</p>}
+    </div>
+  );
+}

