}

for (const [name, scenario] of Object.entries({
  "hidden or deleted profile": { directoryStatus: 404 },
  "Directory outage": { directoryStatus: 503 },
  "revoked credentials": { credentialsDenied: true },
  "Directory permission refusal": { directoryStatus: 403 },
  "different token owner": { userinfoSub: "another-person" },
  "changed organization": { userinfoHd: "elsewhere.example" },
  "inconsistent Directory identity": { directoryEmail: "other@workspace.example" },
})) {
  test(`existing session denies protected access after ${name}`, async ({ page, request }) => {
    await signIn(page);
    await expect(page.getByRole("heading", { name: "Your Workspace profile" })).toBeVisible();
    await request.post("http://127.0.0.1:3101/control", { data: scenario });
    await page.reload();
    await expect(
      page.getByRole("heading", {
        name: /Workspace profile unavailable|Reconnect your Google account/,
      }),
    ).toBeVisible();
    await expect(page.getByText("contact@example.org")).toHaveCount(0);
    await expect(page.getByText("member@workspace.example")).toHaveCount(0);
    await page.getByRole("button", { name: "Sign out", exact: true }).click();
    await expect(page.getByRole("button", { name: "Sign in with Google" })).toBeVisible();
  });
}

test("unreturned contact fields are unavailable, not empty stored values", async ({
  page,
  request,
}) => {
  await request.post("http://127.0.0.1:3101/control", { data: { emails: null, phones: null } });
  await signIn(page);
  await expect(page.getByRole("heading", { name: "Your Workspace profile" })).toBeVisible();
  await expect(page.getByText("Unavailable", { exact: true })).toHaveCount(2);
  await request.post("http://127.0.0.1:3101/control", { data: { emails: [], phones: [] } });
  await page.reload();
  await expect(page.getByText("No shared entries", { exact: true })).toHaveCount(2);
});

test("primary-email changes retain the Directory identity and target parameters cannot select another user", async ({
  page,
  request,
}) => {
  await signIn(page);
  await expect(page.getByText("member@workspace.example", { exact: true })).toBeVisible();
  const { state } = await (await request.get("http://127.0.0.1:3101/control")).json();
  expect(state.sub).not.toBe(state.directoryId);
  await request.post("http://127.0.0.1:3101/control", {
    data: { email: "renamed@workspace.example" },
  });
  await page.goto(
    "/profile?userId=another-person&directoryId=another-person&email=other%40workspace.example",
  );
  await expect(page.getByText("renamed@workspace.example", { exact: true })).toBeVisible();
  const { requests } = await (await request.get("http://127.0.0.1:3101/control")).json();
  const last = requests
    .filter((entry: { url: string }) => entry.url.includes("/directory/"))
    .at(-1);
  expect(decodeURIComponent(new URL(last.url).pathname.split("/").at(-1)!)).toBe(state.directoryId);
  await page.getByRole("button", { name: "Sign out", exact: true }).click();
  await expect(page.getByRole("button", { name: "Sign in with Google" })).toBeVisible();
  await signIn(page);
  await expect(page.getByText("renamed@workspace.example", { exact: true })).toBeVisible();
});

test("an existing identity is never rebound when its Directory user disappears", async ({
  page,
  request,
}) => {
  await signIn(page);
  await expect(page.getByRole("heading", { name: "Your Workspace profile" })).toBeVisible();
  await request.post("http://127.0.0.1:3101/control", {
    data: { directoryId: "replacement-user", name: "Someone else" },
  });
  await page.reload();
  await expect(page.getByRole("heading", { name: "Workspace profile unavailable" })).toBeVisible();
  await expect(page.getByText("Someone else")).toHaveCount(0);
  await page.getByRole("button", { name: "Sign out", exact: true }).click();
  await expect(page.getByRole("button", { name: "Sign in with Google" })).toBeVisible();
  await signIn(page);
  await expect(
    page.getByRole("alert").filter({ hasText: "Sign-in could not be completed" }),
  ).toBeVisible();
});

test("a different Google subject cannot claim an already-bound Directory identity", async ({
  page,
  request,
}) => {
  await signIn(page);
  await expect(page.getByRole("heading", { name: "Your Workspace profile" })).toBeVisible();
  await page.getByRole("button", { name: "Sign out", exact: true }).click();
  await expect(page.getByRole("button", { name: "Sign in with Google" })).toBeVisible();
  await request.post("http://127.0.0.1:3101/control", { data: { sub: "replacement-subject" } });
  await signIn(page);
  await expect(
    page.getByRole("alert").filter({ hasText: "Sign-in could not be completed" }),
  ).toBeVisible();
});

test("expired access tokens refresh on the server using the same identity", async ({
  page,
  request,
}) => {
  await request.post("http://127.0.0.1:3101/control", { data: { tokenExpiresIn: 1 } });
  await signIn(page);
  await expect(page.getByRole("heading", { name: "Your Workspace profile" })).toBeVisible();
  const { requests } = await (await request.get("http://127.0.0.1:3101/control")).json();
  expect(
    requests.some(
      (entry: { body: string }) =>
        new URLSearchParams(entry.body).get("refresh_token") === "google-refresh-token",
    ),
  ).toBe(true);
  expect(
    requests.some(
      (entry: { url: string; authorization: string }) =>
        entry.url.includes("/directory/") &&
        entry.authorization === "Bearer refreshed-google-token",
    ),
  ).toBe(true);
});

test("failed token refresh requires reconnection without showing stale profile data", async ({
