display.text:
import { AuthButton } from "@/components/auth-button";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

export default async function Home({
  searchParams,
}: {
  searchParams: Promise<{ error?: string }>;
}) {
  const { error } = await searchParams;
  return (
    <main className="mx-auto flex w-full max-w-xl flex-1 flex-col justify-center p-6">
      <Card>
        <CardHeader>
          <CardTitle className="text-3xl font-semibold tracking-tight">
            <h1>Binden</h1>
          </CardTitle>
          <CardDescription>
            Sign in with your managed Google Workspace account to view your current shared profile.
          </CardDescription>
        </CardHeader>
        {error && (
          <CardContent>
            <Alert variant="destructive">
              <AlertTitle>Sign-in could not be completed</AlertTitle>
              <AlertDescription>
                Use your organization’s managed account and grant Directory read access. Your
                profile must be visible in Workspace.
              </AlertDescription>
            </Alert>
          </CardContent>
        )}
        <CardFooter>
          <AuthButton />
        </CardFooter>
      </Card>
    </main>
  );
}

